import React from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

export default function CommitteeTree() {
  return (
    <section className="py-10 px-4 overflow-x-auto">
      <h2 className="text-2xl font-bold text-center mb-12">Our Committee</h2>

      <div className="flex flex-col items-center space-y-16">

        {/* President */}
        <div className="relative flex flex-col items-center">
          <MemberCard {...roles[0]} />
          {/* Line to next row */}
          <div className="absolute top-full h-8 border-l border-gray-400"></div>
        </div>

        {/* Vice President, Secretary, Treasurer */}
        <div className="relative flex justify-center items-center space-x-12">
          {roles.slice(1).map((role, index) => (
            <div className="relative flex flex-col items-center" key={index}>
              <MemberCard {...role} />
              {/* Line to next row */}
              <div className="absolute top-full h-8 border-l border-gray-400"></div>
            </div>
          ))}
          {/* Horizontal line connecting all three */}
          <div className="absolute top-0 left-0 right-0 h-0.5 border-t border-gray-400 mt-20"></div>
        </div>

        {/* Member Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-6">
          {members.map((member, index) => (
            <MemberCard key={index} {...member} />
          ))}
        </div>
      </div>
    </section>
  );
}

function MemberCard({ img, title, name }) {
  return (
    <div className="text-center p-4 border rounded shadow w-32 bg-white">
      <img
        src={img}
        alt={title}
        className="w-16 h-16 mx-auto rounded-full mb-2 border"
      />
      <div className="font-semibold text-sm">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}
